import {imageData,videoData} from './intake-media.js';
import {createCaptureController} from './capture.js';
import {createPressToTalk} from './press-to-talk.js';
import {createOnboardingSpeech} from './onboarding-speech.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createIntakeUI({api,exampleMode,root,redraw,onDone}){
 let s,epoch=0,active=false,recordingStarted=false;
 const speech=createOnboardingSpeech();
 const capture=createCaptureController({onChange(){updateRecording();},onError(message){s.error=message;updateRecording();}});
 const talk=createPressToTalk({capture,onChange:updateRecording,onSend:transcribe});
 function reset(){stop();s={step:'capture',photos:[],video:null,document:null,text:'',turns:[],answer:'',draft:null,error:'',busy:false,key:crypto.randomUUID(),commit:null};active=true;}
 function stop(){active=false;epoch++;talk.cancel();speech.cancel();capture.emergencyStop();}
 function updateRecording(){if(!active)return;const button=root.querySelector('#intake-hold'),live=root.querySelector('#intake-live');if(button){button.classList.toggle('recording',talk.state.holding);button.classList.toggle('cancel-recording',talk.state.cancelling);button.textContent=talk.state.cancelling?'松手取消':talk.state.holding?'松开发送 · 上滑取消':talk.state.finishing?'正在转写…':'按住说话';}if(live)live.textContent=talk.state.live||s.error||(talk.state.holding?'正在听，最长 60 秒…':'');if(capture.media.voiceRecorder)recordingStarted=true;if(recordingStarted&&talk.state.holding&&!capture.media.voicePending&&!capture.media.voiceRecorder&&capture.media.audioUrl)void talk.end();}
 async function transcribe(url){const ticket=epoch;const r=await speech.transcribe(url);if(!active||ticket!==epoch||!r)return;if(r.error)s.error=r.error;else{s.answer=r.text;s.error='';}redraw();}
 function images(){return [...s.photos.slice(0,2).map(dataUrl=>({kind:'photo',dataUrl})),...(s.video?.frames||[]).map(dataUrl=>({kind:'video',dataUrl})),...(s.document?[{kind:'document',dataUrl:s.document}]:[])];}
 const button=(label,action,cls='button secondary',extra='')=>`<button type="button" class="${cls}" data-intake="${action}" ${s.busy?'disabled':''} ${extra}>${label}</button>`;
 function render(){active=true;if(!s)reset();
  const steps=['拍下它','说说它','确认档案'],index=s.step==='capture'?0:s.step==='review'?2:1;
  let html=`<div class="intake-steps" aria-label="建档进度">${steps.map((label,i)=>`<span class="${i===index?'active':''}">${i+1} ${label}</span>`).join('')}</div>`;
  if(s.step==='capture')html+=`<div class="intake-intro"><h1>先认识这张小脸</h1><p>拍张照片或一段视频，再聊聊它的日常。</p></div><div class="intake-media">${s.photos.map((p,i)=>`<figure><img src="${p}" alt="宠物照片 ${i+1}">${button('移除','remove-photo','text-button',`data-index="${i}"`)}</figure>`).join('')}${s.video?`<figure><video src="${s.video.dataUrl}" controls playsinline></video>${button('移除视频','remove-video','text-button')}</figure>`:''}${!s.photos.length&&!s.video?'<div class="intake-camera-mark" aria-hidden="true">◎</div>':''}</div><div class="intake-media-actions">${button('拍照','camera','button primary')}${button('录视频','video')}${button('选相册','album')}</div><input hidden id="intake-camera" type="file" accept="image/*" capture="environment"><input hidden id="intake-album" type="file" accept="image/jpeg,image/png,image/webp" multiple><input hidden id="intake-video" type="file" accept="video/mp4,video/webm" capture="environment"><p class="online-note">最多 3 张照片 · 视频 30 秒 / 10 MB 以内<br>视频抽帧辅助整理，原视频会保留。</p><details class="intake-material"><summary>有体检单或疫苗记录？顺手拍下来</summary><p class="online-note">材料文字仅本站可见，确认后再选取内容写入档案。</p>${button(s.document?'更换材料':'拍摄 / 上传材料','document')}${s.document?'<span class="live-tag">已添加材料</span>'+button('移除','remove-document','text-button'):''}<input hidden id="intake-document" type="file" accept="image/*"></details>${exampleMode?button('载入示例照片与口述','sample','button secondary full spaced'):''}${button('拍好了，聊聊它','describe','button primary full spaced',!s.photos.length&&!s.video?'disabled':'')}`;
  else if(s.step==='describe')html+=`<div class="intake-agent-heading"><span>✦</span><div><strong>建档小助手</strong><small>${exampleMode?'预设示例 · 不调用真实 AI':'只整理你提供的资料，一起把它了解清楚'}</small></div></div><div class="intake-conversation">${s.turns.map(t=>`<div class="chat-bubble ${t.role==='user'?'mine':''}">${esc(t.text)}</div>`).join('')}<div class="chat-bubble">${esc(s.draft?.nextQuestion||'它叫什么？说说你知道的年龄、日常和最近的健康情况，想到什么就说什么。')}</div></div><div class="intake-composer">${exampleMode?button('使用示例回答','sample-answer','button secondary full'):'<button type="button" id="intake-hold" class="online-voice">按住说话</button>'}<p id="intake-live" class="intake-live" aria-live="polite"></p><label for="intake-answer">${s.answer?'确认转写内容，也可以直接修改':'也可以打字'}</label><textarea id="intake-answer" rows="3" maxlength="4000" placeholder="说完后文字会出现在这里，确认后再整理。">${esc(s.answer)}</textarea>${capture.media.audioUrl?`<audio controls src="${capture.media.audioUrl}"></audio>${button('重新转写','retry-speech','text-button')}`:''}${button(s.busy?'正在整理…':'确认这段，继续聊','analyze','button primary full spaced')}${s.draft?`<div class="intake-minor-actions">${button('这项不清楚','unknown','text-button')}${button('先确认现有档案','review','text-button')}</div>`:button('返回照片','capture','text-button')}</div>`;
  else if(s.step==='review'){const d=s.draft;html+=`<h1>一起确认，就建好了</h1><p class="online-note">你确认的内容才会成为宠物 AI 分身的依据。</p><form id="intake-confirm" class="form-stack"><fieldset class="intake-fields" ${s.commit?'disabled':''}><label>名字<input name="name" required maxlength="80" value="${esc(d.name)}"></label><label>它是<select name="species"><option value="unknown" ${d.species==='unknown'?'selected':''}>还需确认</option><option value="cat" ${d.species==='cat'?'selected':''}>猫咪</option><option value="dog" ${d.species==='dog'?'selected':''}>狗狗</option></select></label><label>整理后的档案<textarea name="description" rows="6" maxlength="4000">${esc(d.description)}</textarea></label><details><summary>年龄、性格与其他信息</summary><label>年龄及依据<input name="age" maxlength="80" value="${esc(d.age)}" placeholder="待确认"></label><label>性格观察<input name="character" maxlength="500" value="${esc(d.character)}"></label><label>性别<select name="sex">${[['unknown','待确认'],['male','男孩子'],['female','女孩子']].map(([v,l])=>`<option value="${v}" ${d.sex===v?'selected':''}>${l}</option>`).join('')}</select></label></details>${d.uncertainties?.length?`<div class="info-box"><strong>留待了解</strong><ul>${d.uncertainties.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>${button('用语音再补充','more','text-button')}</div>`:''}${d.ocrText?`<details><summary>材料识别文字 · 仅本站可见</summary><p style="white-space:pre-wrap">${esc(d.ocrText)}</p><small>如需分享某条记录，请核对原件后补充到上方档案。</small></details>`:''}<label class="check-label"><input type="checkbox" name="published"><span>同时向领养者展示<small>未勾选时先保存为本站档案，照片和视频也不公开。</small></span></label></fieldset><button class="button primary full" ${s.busy?'disabled':''}>${s.busy?'正在保存…':s.commit?'重试保存同一份档案':'确认并建立档案'}</button>${s.commit?'':button('返回对话补充','more','text-button')}</form>`;}
  return `<section class="intake-flow">${html}<p class="online-error" role="alert">${esc(s.error)}</p>${s.busy?'<p role="status">正在处理，请稍候…</p>':''}</section>`;
 }
 function remember(){const a=root.querySelector('#intake-answer');if(a)s.answer=a.value;const f=root.querySelector('#intake-confirm');if(f&&s.draft&&!s.commit){const data=new FormData(f);for(const k of ['name','species','description','age','character','sex'])s.draft[k]=String(data.get(k)||'');}}
 async function analyze(unknown=false){remember();if(!unknown&&!s.answer.trim()){s.error='先说一段，或输入你了解的情况。';redraw();return;}const question=s.draft?.nextQuestion||'请介绍这位伙伴';const answer=unknown?'这项不清楚，先保留待确认。':s.answer.trim();const text=[s.text,`助手提问：${question}\n救助者口述：${answer}`].filter(Boolean).join('\n');if(text.length>12000)throw Error('这次口述内容较多，请先确认已有档案，再补充日常。');const result=await api.draftIntake({text,images:images()});s.text=text;s.turns.push({role:'assistant',text:question},{role:'user',text:answer});s.draft=result;s.answer='';await capture.reset();if(!result.nextQuestion)s.step='review';}
 async function action(e){const b=e.target.closest('[data-intake]');if(!b||b.disabled||s.busy||talk.state.holding||talk.state.finishing)return;const a=b.dataset.intake;remember();if(['camera','album','video','document'].includes(a)){root.querySelector('#intake-'+a).click();return;}s.error='';
  if(a==='retry-speech'){await transcribe(capture.media.audioUrl);return;}
  const ticket=epoch,previousStep=s.step;s.busy=true;
  try{if(a==='remove-photo')s.photos.splice(Number(b.dataset.index),1);else if(a==='remove-video')s.video=null;else if(a==='remove-document')s.document=null;
   else if(a==='sample'){const r=await fetch('./assets/orange.jpg');if(!r.ok)throw Error('示例照片暂不可用');s.photos=[await imageData(await r.blob())];s.answer='它叫小满，平时喜欢逗猫棒，年龄不清楚。';}
   else if(a==='sample-answer')s.answer=s.draft?'目前没有检查报告，健康情况还需要确认。':'它叫小满，平时喜欢玩羽毛逗猫棒，估计一岁，具体生日不清楚。';
   else if(a==='describe'||a==='capture')s.step=a;
   else if(a==='more'){s.step='describe';s.commit=null;s.key=crypto.randomUUID();s.draft.nextQuestion='还有哪些你想补充或更正的情况？';}
   else if(a==='review')s.step='review';
   else if(a==='analyze'||a==='unknown'){redraw();await analyze(a==='unknown');}
  }catch(err){s.error=err.message;}finally{if(active&&ticket===epoch){s.busy=false;redraw();if(s.step!==previousStep)root.scrollIntoView?.({block:'start'});}}
 }
 async function change(e){const el=e.target;if(!el.id?.startsWith('intake-')||el.type!=='file'||!el.files?.length)return;s.busy=true;s.error='';const ticket=epoch,files=Array.from(el.files);redraw();try{if(el.id==='intake-video')s.video=await videoData(files[0]);else if(el.id==='intake-document')s.document=await imageData(files[0]);else{if(files.length+s.photos.length>3)throw Error('最多添加 3 张照片，请先移除一张。');for(const f of files)s.photos.push(await imageData(f));}}catch(err){s.error=err.message;}finally{if(active&&ticket===epoch){s.busy=false;redraw();}}}
 async function submit(e){if(e.target.id!=='intake-confirm')return;e.preventDefault();e.stopImmediatePropagation();if(s.busy)return;remember();if(!s.draft.name.trim()||s.draft.species==='unknown'){s.error='请确认它的名字和猫咪 / 狗狗类别。其他不确定的内容可以留空。';redraw();return;}if(!s.commit){const d=s.draft;s.commit={name:d.name,profile:{species:d.species,description:d.description,age:d.age,character:d.character,sex:d.sex},published:new FormData(e.target).has('published'),text:s.text,ocrText:d.ocrText,photos:s.photos.length?s.photos:[s.video.frames[0]],...(s.video?{video:s.video.dataUrl}:{})};}s.busy=true;s.error='';redraw();try{const result=await api.commitIntake(s.commit,s.key);s.busy=false;await onDone(result);}catch(err){s.error='保存未确认，草稿已保留。请重试；同一份档案不会重复建立。';s.busy=false;redraw();}}
 function bind(){if(!active)return;const stream=root.querySelector('.intake-conversation');if(stream)stream.scrollTop=stream.scrollHeight;const el=root.querySelector('#intake-hold');if(el){el.disabled=s.busy;el.oncontextmenu=e=>e.preventDefault();el.onpointerdown=e=>{if(e.button!==0||s.busy)return;e.preventDefault();el.setPointerCapture(e.pointerId);recordingStarted=false;void talk.start(e.clientY);};el.onpointermove=e=>talk.move(e.clientY);el.onpointerup=()=>void talk.end();el.onpointercancel=()=>void talk.end(true);el.onkeydown=e=>{if([' ','Enter'].includes(e.key)&&!e.repeat){e.preventDefault();recordingStarted=false;void talk.start(0);}};el.onkeyup=e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();void talk.end();}};updateRecording();}}
 root.addEventListener('click',e=>{if(active)void action(e);});root.addEventListener('change',e=>{if(active)void change(e);});root.addEventListener('input',()=>{if(active)remember();});root.addEventListener('submit',submit,true);
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&active)void talk.end(true);});
 return {render,bind,reset,stop,get busy(){return !!s?.busy||talk.state.holding||talk.state.finishing;}};
}
